var actor=ctx.roles.actor;
function object(value){return value!==null&&!Array.isArray(value)&&typeof value==='object';}
function validProfile(value){if(!object(value))return false;var keys=Object.keys(value).sort(),allowed=['appearance','biography','playerNotes','pronouns'];if(keys.length<1||keys.length>4)return false;for(var i=0;i<keys.length;i++){if(allowed.indexOf(keys[i])<0)return false;var text=value[keys[i]],max=keys[i]==='pronouns'?200:(keys[i]==='appearance'?5000:20000);if(typeof text!=='string'||text.trim()!==text||text.length<1||text.length>max)return false;}return true;}
if(!object(ctx.input)||!['correct','record'].includes(ctx.input.mode))throw new Error('Input must contain mode record or correct and one or more profile fields.');
var supplied=Object.keys(ctx.input).filter(function(key){return key!=='mode';}),profile={};for(var i=0;i<supplied.length;i++)profile[supplied[i]]=ctx.input[supplied[i]];
if(Object.keys(ctx.input).length!==supplied.length+1||!validProfile(profile))throw new Error('Identity must contain only one or more trimmed pronouns, appearance, biography, and playerNotes fields.');
var raw=actor.components['dnd2024.character.identity'],prior=null;if(raw){try{prior=JSON.parse(raw);}catch(error){throw new Error('Existing profile is malformed and requires governed migration.');}if(!validProfile(prior))throw new Error('Existing profile is invalid and requires governed migration.');}
if(ctx.input.mode==='record'&&raw)throw new Error('record requires absent profile state.');if(ctx.input.mode==='correct'&&!raw)throw new Error('correct requires existing valid profile state.');
var canonical={};['pronouns','appearance','biography','playerNotes'].forEach(function(key){if(Object.prototype.hasOwnProperty.call(profile,key))canonical[key]=profile[key];});
return {narration:actor.name+' profile is '+(raw?'corrected.':'recorded.'),effects:[{type:raw?'component.set':'component.add',entityId:actor.id,definitionId:'dnd2024.character.identity',data:JSON.stringify(canonical)}],events:[],notifications:[],data:{actorId:actor.id,profile:canonical,previousProfile:prior}};
